def composantes(graphe):
    vus = set()

    def explorer(sommet):
        vus.add(sommet)
        for voisin in graphe[sommet]:
            if voisin not in vus:
                explorer(voisin)

    nombre = 0
    for sommet in graphe:
        if sommet not in vus:
            nombre += 1
            explorer(sommet)
    return nombre

